#!/usr/bin/env python3
"""Build Week 10 QMD from editable lecture content + shared JS file."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; DEST=ROOT/'week10'/'week10.qmd'
slides=[]

def s(title, content, cls='concept-slide', notes=''):
    slides.append(f"## {title} {{.{cls}}}\n\n{content.strip()}\n"+(f"\n::: {{.notes}}\n{notes.strip()}\n:::\n" if notes else ''))
def fig(name,alt,height='12.1em'):
    return f'<div class="w10-figure" style="height:{height};"><img src="figures/{name}.svg" alt="{alt}"></div>'
def kick(text):return f'<div class="eyebrow">{text}</div>'
def claim(text):return f'<div class="concept-line fragment fade-up">{text}</div>'
def note(text,warning=False):return f'<div class="{("warning-box" if warning else "definition-box")} fragment fade-up"><p>{text}</p></div>'
def cards(items):
    return '<div class="w10-card-grid">' + ''.join(f'<div class="w10-card {b}"><div class="w10-card-label">{k}</div><div class="w10-card-large">{v}</div><div class="w10-card-small">{t}</div></div>' for k,v,t,b in items) + '</div>'
def steps(items):return '<div class="w10-step-stack">'+''.join(f'<div class="w10-step"><span class="w10-num">{i+1:02d}</span><strong>{a}</strong><span>{b}</span></div>' for i,(a,b) in enumerate(items))+'</div>'
def compare(rows,headers):
    return '<div class="w10-table" style="--cols:'+str(len(headers))+'">'+''.join(f'<div class="w10-th">{x}</div>' for x in headers)+''.join(f'<div>{x}</div>' for row in rows for x in row)+'</div>'

yaml='''---
title: "Statistics for Pharmacists"
subtitle: "Week 10 · Pharmaceutical and clinical statistics"
author: "Graduate Pharmaceutical Studies"
date: ""
title-slide-attributes:
  data-footer: ""
format:
  revealjs:
    footer: "Statistics 101 · Week 10"
    scrollable: false
    transition: fade
    theme:
      - default
      - ../assets/scss/course.scss
      - ../assets/scss/week10.scss
    resources:
      - figures/**
---
\n'''

s('Pharmaceutical and clinical statistics',kick('Week 10 · From statistical methods to pharmaceutical evidence')+'<div class="w10-hero">How does statistics enter <strong>actual pharmaceutical evidence</strong>?</div>'+cards([('Observational','Association','How frequent? What is associated?','observed'),('Diagnostic','Classification','Can a biomarker identify disease?','uncertainty'),('Experimental','Causal effects','Does a treatment help or harm?','estimate')]),'title-slide')
s('Today: one evidence chain',kick('Not another catalog of tests')+'<div class="w10-evidence-flow"><div>Populations<span>epidemiology</span></div><b>→</b><div>Patients<span>diagnostics</span></div><b>→</b><div>Interventions<span>clinical trials</span></div><b>→</b><div>Exposure<span>toxicology</span></div><b>→</b><div>Knowledge<span>meta-analysis</span></div></div>'+claim('The question and study design determine the interpretation; statistical machinery quantifies <strong>effects and uncertainty</strong>.'))
s('First: can we intervene?',kick('Return to Week 03 · study design')+cards([('Observe','Exposure is not allocated','Cohort / case–control / cross-sectional studies','observed'),('Randomize','Exposure is allocated','Controlled trial with prespecified endpoints','estimate')])+note('Both designs have sampling variability. Random allocation helps break systematic links between measured <em>and unmeasured</em> baseline confounders on average.'),'concept-slide')
s('What observations cannot guarantee',kick('Association ≠ causation')+steps([('Confounding','A common cause affects exposure and outcome.'),('Selection bias','Who enters or remains in the study can distort an association.'),('Measurement bias','Inconsistent exposure or outcome ascertainment changes estimates.')])+claim('A small $p$-value cannot repair a flawed data-generating process.'))

s('Prevalence: how many are affected now?',kick('Disease burden · stock of existing cases')+'<div class="w10-bigmath">$\\mathrm{Prevalence}=\\dfrac{\\text{existing cases}}{\\text{population at time / period}}$</div>'+cards([('Illustrative population','1,000 people','Observed at the start of the year','observed'),('Already affected','50 people','Point prevalence = 50 / 1,000 = 5%','model')])+note('Prevalence describes population burden. It reflects both arrival of new cases and how long people remain cases.'))
s('Incidence: how many become affected?',kick('New events among people initially at risk')+fig('incidence_prevalence','Synthetic population illustrates prevalence and new cases over a period','10.5em')+'<div class="w10-equation">$\\text{Cumulative incidence}=40/950\\approx4.2\\%$ during 1 year</div>'+note('Cumulative incidence is a risk over a specified time horizon, assuming appropriate follow-up and accounting for censoring when needed.'))
s('Incidence rate uses person-time',kick('A different denominator and unit')+'<div class="w10-bigmath">$\\text{Incidence rate}=\\dfrac{\\text{new cases}}{\\sum\\text{person-time at risk}}$</div>'+cards([('Example','40 new cases','Among a dynamic followed population','observed'),('Observed time','900 person-years','Different people contribute different durations','model'),('Incidence rate','4.44 / 100 person-years','An event rate, not a 4.44% probability','estimate')])+claim('Rate and probability become close only under additional conditions, including relatively low risk over the time horizon.'))

s('Revisit the invisible third variable',kick('Synthetic association · sugary drinks → school performance')+fig('confounding_dag','Causal directed acyclic graph with household resources influencing both sugary drinks and performance','10.8em')+claim('Household resources $Z$ can be a <strong>confounder</strong> if it is a common cause of $X$ and $Y$; a mediator would have a different causal role.'))
s('An association that vanishes when pooled',kick('Compare within the low- and high-rent strata')+fig('confounding_strata','Risk of bad school performance by drink intake within strata and pooled, with exact synthetic counts','12.6em')+'<div class="w10-small-note">Low rent: 4/40 versus 12/60 · high rent: 36/60 versus 24/30 · pooled: 40/100 versus 36/90. All counts synthetic.</div>')
s('Confounder or effect modifier?',kick('Two different scientific questions')+compare([('Confounding','An overall estimate is distorted by differing group compositions','Adjustment aims at an association net of the confounding pathway'),('Effect modification','Exposure–outcome associations genuinely differ between strata','Report the strata; an overall effect can conceal clinically useful differences')],['Concept','What happens?','What should we do?'])+note('Our synthetic drink example illustrates both: RR within low rent = 2.0; within high rent = 1.33; pooled RR = 1.0.'))
s('The hospital paradox, once again',kick('Drug response across three hospitals')+fig('hospital_simpson','Treatment better at each of three hospitals yet worse after pooling due to differing case mix','12.6em')+'<div class="w10-small-note">Drug: 30%, 60%, 90% success in hospitals A/B/C; control: 20%, 50%, 80%. Different arm allocations create the pooled reversal.</div>')
s('When the confounder is measured',kick('Design and analysis options')+steps([('Before data collection','Restriction or matching can improve comparability; randomization addresses baseline confounding by design.'),('During analysis','Stratify, standardize or adjust using regression; always inspect effect modification.'),('If effects are broadly common','Mantel–Haenszel estimates an adjusted association across strata (with a clear target estimand).')])+note('A common pooled effect is not appropriate when stratum-specific treatment effects differ substantially.'))
s('What if confounding is unobserved?',kick('A fundamental limit of observational evidence')+cards([('Propensity methods','Measured covariates','Matching / weighting / adjustment can balance observed confounders','observed'),('Sensitivity analysis','Unmeasured covariates','Ask how strong hidden confounding must be to reverse a result','uncertainty'),('Triangulate','Different designs','Compare evidence across designs with different weaknesses','estimate')])+note('Propensity scores do <strong>not</strong> automatically solve unmeasured confounding; more sophisticated methods are outside this course.',True))

s('Epidemiology: which effect measure?',kick('Use incidence for risk; distinguish risk from odds')+compare([('Risk $p$','Events / people at risk','Probability over a specified period'),('Odds','$p/(1-p)$','Event relative to non-event probability'),('Relative risk (RR)','$p_T/p_C$','Relative event risk: multiplicative'),('Odds ratio (OR)','$[p_T/(1-p_T)]/[p_C/(1-p_C)]$','Multiplicative odds, not risk'),('Risk difference (RD)','$p_T-p_C$','Absolute percentage-point difference')],['Measure','Formula','Interpretation'])+'<div class="w10-small-note">$T$ = exposed / treated; $C$ = comparator. Choose a time horizon and clear event definition.</div>')
s('Same RR, very different absolute impact',kick('Why baseline risk matters')+fig('relative_absolute_risk','Two treatment examples have same relative risk but very different absolute risk differences','12.4em')+claim('A $50\\%$ relative reduction can mean <strong>1</strong> or <strong>20</strong> events prevented per 100 patients, depending on baseline risk.'))
s('Worked example: risk and risk difference',kick('Synthetic one-year prevention trial')+cards([('Comparator risk','20%','20 events per 100 patients','model'),('Treatment risk','10%','10 events per 100 patients','observed'),('RR','0.50','Half the event risk under treatment','estimate'),('ARR','10 percentage points','0.20 − 0.10 = 0.10','uncertainty')])+claim('Absolute and relative summaries describe the <strong>same contrast</strong>, on different scales.'))
s('NNT and NNH: put consequences on the same page',kick('Number needed to treat / harm')+cards([('Benefit','NNT = 10','ARR = 0.10 → one additional prevented event per 10 treated, on average','estimate'),('Harm','NNH = 25','Absolute harm increase 0.04 → one additional adverse event per 25 treated, on average','warning')])+note('Specify comparator, population, endpoint and time horizon. NNT does not identify which patient benefits, and comparing NNT/NNH needs clinical weighting of outcomes.'))
s('Attributable fractions: causal language needs care',kick('Illustrative association · exposure raises risk from 10% to 20%')+'<div class="w10-formula-pair"><div><strong>Among exposed</strong><span>$AF_E=(RR-1)/RR=50\\%$</span><small>Fraction of exposed cases attributed to exposure, if association is causal</small></div><div><strong>In population</strong><span>$PAF=(R_{pop}-R_0)/R_{pop}\\approx23\\%$</span><small>With 30% exposed: population risk = 13%, baseline risk = 10%</small></div></div>'+note('Attributable fractions are <strong>not</strong> causal without assumptions about confounding, timing and intervention effects.'))

s('Diagnostic tests: from association to classification',kick('Return to Bayes · Week 01')+cards([('Test accuracy','Sensitivity / specificity','How often the test correctly classifies reference-standard outcomes','observed'),('Population context','Prevalence','How common the target condition is in the tested population','model'),('Patient interpretation','PPV / NPV','How likely a result is to indicate disease / health','uncertainty')])+claim('Accuracy statistics alone do not tell us how much to trust a <strong>positive</strong> test.'))
s('Start from four patients categories',kick('Positive / negative test × present / absent condition')+fig('confusion_matrix','Two by two diagnostic classification matrix with true positives, false positives, false negatives and true negatives','11.8em')+'<div class="w10-equation">$\\mathrm{Sensitivity}=TP/(TP+FN)$ &nbsp;&nbsp; $\\mathrm{Specificity}=TN/(TN+FP)$</div>')

conf='''<div class="w10-conf-widget" id="confWidget">
<div class="w10-conf-left">
<div class="w10-mini-title">Edit the patient counts</div>
<div class="w10-count-grid">
<div class="w10-input-cell"><label class="w10-control">TP · sick & positive<input id="cmTP" type="number" min="0" step="1" value="38"></label></div>
<div class="w10-input-cell"><label class="w10-control">FN · sick & negative<input id="cmFN" type="number" min="0" step="1" value="8"></label></div>
<div class="w10-input-cell"><label class="w10-control">FP · healthy & positive<input id="cmFP" type="number" min="0" step="1" value="12"></label></div>
<div class="w10-input-cell"><label class="w10-control">TN · healthy & negative<input id="cmTN" type="number" min="0" step="1" value="142"></label></div>
</div>
<div class="w10-highlight-metrics"><div><span>Sensitivity</span><strong id="cmSensBig">—</strong></div><div><span>Specificity</span><strong id="cmSpecBig">—</strong></div><div><span>PPV</span><strong id="cmPpvBig">—</strong></div><div><span>NPV</span><strong id="cmNpvBig">—</strong></div></div>
<div class="w10-mini-note">Undefined denominators display “—”. Counts must be nonnegative whole numbers.</div>
</div>
<div class="w10-conf-right">
<div class="w10-mini-title">Explore the full diagnostic vocabulary · 5 columns × 6 metrics</div>
<div class="w10-metric-grid" id="cmMetrics"></div>
</div>
</div>'''
s('Interactive lab · thirty diagnostic metrics',kick('Numbers change together · meaning depends on the denominator')+conf,'exercise-slide', 'Focus on sensitivity, specificity, PPV, NPV; the more advanced metrics are for recognition, not memorization.')
s('A metric is a question with a denominator',kick('Read the conditioning, not just the abbreviation')+compare([('Sensitivity / recall','Of those truly sick, what fraction tests positive?','$TP/(TP+FN)$'),('Specificity','Of those truly healthy, what fraction tests negative?','$TN/(TN+FP)$'),('PPV','Of those testing positive, what fraction is sick?','$TP/(TP+FP)$'),('NPV','Of those testing negative, what fraction is healthy?','$TN/(TN+FN)$')],['Metric','Clinical interpretation','Definition'])+claim('Sensitivity and specificity condition on <em>reference disease status</em>; predictive values condition on the <em>observed test result</em>.'))
s('A diagnostic marker needs a decision threshold',kick('Last week: a probability model · today: an action')+steps([('Measure','A continuous biomarker varies across sick and healthy people.'),('Classify','Choose a cutoff: trade missed cases against false alarms.'),('Validate','Estimate sensitivity, specificity and calibration in a new relevant population.')])+note('A model threshold that maximizes an in-sample statistic may be too optimistic in new patients.'))
roc='''<div class="w10-lab" id="rocWidget">
<div class="w10-controls">
<label class="w10-control">Biomarker (synthetic study)<select id="rocMarker"><option value="ferritin">Ferritin · strong separation</option><option value="folate">Folate · weak separation</option></select></label>
<label class="w10-control">Positive if marker ≤ <strong id="rocCutVal">30</strong><input id="rocCut" type="range" min="0" max="110" value="30" step="1"></label>
<div class="w10-micro">Drag the red threshold line on the left plot; the current operating point moves on the ROC.</div>
<div class="w10-two-output"><div class="w10-output"><span>Sensitivity</span><strong id="rocSen">—</strong></div><div class="w10-output"><span>Specificity</span><strong id="rocSpe">—</strong></div><div class="w10-output"><span>AUC · fixed per marker</span><strong id="rocAuc">—</strong></div><div class="w10-output"><span>Youden cutoff (sample)</span><strong id="rocBest">—</strong></div></div>
</div>
<div class="w10-visual"><svg id="rocSvg" class="w10-svg" viewBox="0 0 900 475" aria-label="Synthetic biomarker dot plot with draggable threshold and corresponding ROC curve"></svg></div>
</div>'''
s('Interactive lab · threshold and ROC',kick('Synthetic iron-deficiency status · disease reference label known')+roc,'exercise-slide','Strong/weak marker distributions are explicitly synthetic and not clinical performance claims. Ferritin values decrease in this simulated iron-deficiency dataset; folate is deliberately weak.')
s('What the ROC curve is showing',kick('Each cutoff gives ONE point; all cutoffs give ONE curve')+compare([('Horizontal axis','$1-\\mathrm{specificity}$','False-positive rate'),('Vertical axis','$\\mathrm{sensitivity}$','True-positive rate'),('AUC','Area under the entire ROC','Discrimination across all cutoffs; does not change when slider moves'),('Upper-left corner','High Se, low FPR','Ideal only if clinical costs and prevalence allow')],['Element','Definition','Interpretation'])+note('Maximum Youden index and shortest distance to the corner are possible cutoff criteria — neither is a universal clinical optimum.'))
s('Which error is more costly?',kick('Clinical thresholds encode clinical decisions')+cards([('High sensitivity','Avoid missed disease','Often acceptable to trigger a confirmatory test','estimate'),('High specificity','Avoid false positives','Important if unnecessary treatment would be risky','warning'),('AUC','Overall ranking performance','AUC alone does not choose a patient-facing threshold','uncertainty')])+claim('Select cutoffs with anticipated costs, prevalence, clinical pathway and independent validation in mind.'))
s('Bayes comes back: PPV changes with prevalence',kick('Illustrative test: sensitivity 90%, specificity 90%')+cards([('Prevalence 1%','PPV = 8.3%','Most positives are false positives at very low prevalence','warning'),('Prevalence 20%','PPV = 69.2%','Positive result becomes substantially more credible','estimate')])+'<div class="w10-bigmath">$PPV=\\dfrac{Se\\times Prev}{Se\\times Prev+(1-Sp)(1-Prev)}$</div>')
s('Diagnostic uncertainty does not stop at the cutoff',kick('A test-accuracy estimate comes from a finite study')+steps([('Report intervals','Sensitivity and specificity have sampling uncertainty; so does AUC.'),('Specify reference standard','Errors in the disease reference label can bias measured diagnostic accuracy.'),('Verify transportability','Prevalence, disease spectrum, laboratories and settings may differ.')])+note('If thresholds are chosen on the same data used for evaluation, apparent accuracy may be optimistic.',True))
s('Pooling samples: when fewer tests can suffice',kick('Group testing · only when assay dilution is acceptable')+fig('pooled_testing','Diagram of pooling patient samples and retesting individuals if pool tests positive','10.3em')+'<div class="w10-equation">Expected tests per person (idealized) $\\approx 1/k + 1-(1-p)^k$</div>'+note('Valid only under an appropriate pooling protocol; lower assay sensitivity after dilution, dependence and prevalence can change whether pooling helps.'))

s('Clinical trials: what randomization buys us',kick('Treatment allocation as a planned intervention')+fig('trial_design_flow','Flow of eligible participants through concealed randomization into treatment and comparator arms','11.8em')+claim('The target is a <strong>causal contrast</strong> under a clearly specified intervention, endpoint, population and follow-up.'))
s('Write the question before running the test',kick('Superiority, noninferiority, equivalence')+compare([('Superiority','Is $T$ better than $C$?','Evidence that the effect exceeds a reference such as zero'),('Noninferiority','Is $T$ not unacceptably worse?','One-sided prespecified margin and appropriate CI'),('Equivalence','Are effects close enough in both directions?','Two-sided margin; TOST / corresponding 90% CI')],['Objective','Clinical question','Statistical logic'])+claim('The same observed treatment difference can support different conclusions depending on the <strong>prespecified question</strong>.'))
s('Every trial needs a defensible comparator',kick('Ethics and interpretability')+cards([('Placebo','When appropriate','Can separate treatment effect from expectations, but ethical constraints apply','uncertainty'),('Active comparator','Standard of care','Tests relative benefit or acceptable loss against existing treatment','estimate'),('No intervention','Sometimes relevant','Not interchangeable with placebo when expectations/attention matter','observed')])+note('Comparator choice is part of the scientific and ethical question, not an afterthought.'))
s('Endpoints: one convincing outcome beats many weak ones',kick('Efficacy, safety and multiplicity')+fig('trial_endpoints','Prespecified primary, supportive secondary, and safety endpoints on separate cards','9.6em')+claim('Define what is measured, when, how and by whom. Multiple confirmatory claims require an error-control strategy.'))
s('Baseline, covariates and missing follow-up',kick('Prevent avoidable ambiguity')+steps([('Before dosing','Record baseline endpoint and prognostic factors; plan any covariate adjustment.'),('During follow-up','Apply identical outcome ascertainment and monitoring principles across arms.'),('At analysis','Define the population to analyze and the assumptions for missing values before seeing outcomes.')])+note('Baseline differences can occur by chance despite proper randomization. Do not use significance testing as a gatekeeper for adjustment.'))
s('Masking and allocation concealment',kick('These prevent different problems')+cards([('Concealment','Before assignment','Prevents knowledge of the upcoming allocation from influencing enrolment','observed'),('Masking','After assignment','Can reduce performance and outcome-assessment biases','model'),('Transparent reporting','Throughout','Specify exactly who was masked and how','estimate')])+claim('Labels like “double blind” are less informative than naming <strong>participants, clinicians, assessors and analysts</strong>.'))
random='''<div class="w10-lab" id="randomWidget">
<div class="w10-controls">
<label class="w10-control">Allocation mechanism<select id="ranMode"><option value="simple">Simple randomization: p = 0.50</option><option value="biased">Biased coin: p = 0.75 toward underrepresented arm</option></select></label>
<div class="w10-button-row"><button id="ranOne" class="w10-button" type="button">Allocate 1</button><button id="ranTen" class="w10-button" type="button">Allocate 10</button><button id="ranReset" class="w10-button secondary" type="button">Reset</button></div>
<div class="w10-two-output"><div class="w10-output"><span>Treatment / control</span><strong id="ranCounts">0 / 0</strong></div><div class="w10-output"><span>Next p(treatment)</span><strong id="ranProbability">0.50</strong></div><div class="w10-output"><span>Allocated</span><strong id="ranTotal">0</strong></div><div class="w10-output"><span>Absolute imbalance</span><strong id="ranGap">0</strong></div></div>
<div class="w10-micro">Balanced-biased-coin allocation is <strong>not</strong> an outcome-adaptive design; it uses prior arm counts only.</div>
</div>
<div class="w10-visual"><svg id="randomSvg" class="w10-svg" viewBox="0 0 900 475" aria-label="Sequential trial assignment and arm balance"></svg></div>
</div>'''
s('Interactive lab · randomize one patient at a time',kick('Watch adaptation to arm imbalance')+random,'exercise-slide')
s('Randomization: not all methods are interchangeable',kick('Use transparent, prespecified rules')+compare([('Simple random','Each assignment independent','Some imbalance is natural, especially in small studies'),('Blocked / stratified','Restrictions preserve balance','Specify blocks, factors and concealment protocol'),('Biased coin','Preferentially corrects imbalance','Assignment probability changes using current counts')],['Design','What it changes','What to remember'])+note('Proper randomization does not guarantee equal arm sizes or eliminate chance variation in prognostic factors.'))
power='''<div class="w10-lab" id="powerWidget">
<div class="w10-controls">
<label class="w10-control">Anticipated absolute effect $\\Delta$<input id="powEffect" type="number" min="0.1" max="100" step="0.5" value="5"></label>
<label class="w10-control">Common planning SD $\\sigma$<input id="powSd" type="number" min="0.1" max="100" step="0.5" value="12"></label>
<label class="w10-control">Two-sided $\\alpha$<select id="powAlpha"><option value="0.10">0.10</option><option value="0.05" selected>0.05</option><option value="0.01">0.01</option></select></label>
<label class="w10-control">Target power<select id="powTarget"><option value="0.8" selected>80%</option><option value="0.9">90%</option><option value="0.95">95%</option></select></label>
<div class="w10-two-output"><div class="w10-output"><span>Required / arm</span><strong id="powN">—</strong></div><div class="w10-output"><span>Total planned</span><strong id="powTotal">—</strong></div><div class="w10-output"><span>Standardized effect</span><strong id="powD">—</strong></div><div class="w10-output"><span>Attained approx. power</span><strong id="powAttained">—</strong></div></div>
<div class="w10-micro" id="powNote">Two independent groups, equal allocation; finite-df t-critical, normal approximation to t-test power.</div>
</div>
<div class="w10-visual"><svg id="powerSvg" class="w10-svg" viewBox="0 0 900 475" aria-label="Power versus sample size for a two-sample treatment comparison"></svg></div>
</div>'''
s('Interactive lab · plan the sample size',kick('A two-arm continuous-endpoint superiority study')+power,'exercise-slide')
s('What goes into sample-size planning?',kick('You cannot compute $n$ without assumptions')+steps([('Clinically important difference','Choose $\\Delta$ on the original outcome scale, not merely an attainable statistical signal.'),('Within-arm SD and α','Higher variability or more stringent α generally needs more patients.'),('Target power and operations','Higher power needs more patients; add credible allowance for attrition and operational limitations.')])+note('The widget gives an illustrative approximation for two independent groups, not a regulatory trial-planning calculation.'))
s('Read a trial result as an effect and its interval',kick('An example reporting sentence')+'<div class="w10-quote">“The treatment reduced systolic blood pressure by an estimated <strong>5 mmHg</strong> relative to control (95% CI <strong>2 to 8 mmHg</strong> reduction), at 12 weeks.”</div>'+cards([('Magnitude','5 mmHg','Is it clinically important?','estimate'),('Uncertainty','95% CI','What range of effects remains compatible with data?','uncertainty'),('Context','12 weeks','Who, when, comparator, adverse effects?','observed')])+note('Statistical significance is not a complete benefit–risk assessment.'))

s('Toxicology: dose, effect and harm',kick('Repeated exposures and nonlinear biological responses')+cards([('Pharmacology','EC50 / IC50','Dose or concentration at a defined half-maximal response','estimate'),('Toxicology','TC50 / LC50','Half-maximal toxic response / 50% lethality in a stated assay','warning'),('Experiment','Doses and times','Exposure schedule and concentration range matter','observed')])+claim('A dose–response model describes a particular endpoint under a particular exposure protocol.'))
s('Sigmoids are useful, not universal',kick('Potency, slope, saturation')+fig('dose_response_families','Sigmoidal dose-response families with shifts in EC50 and slope changes','12.2em')+note('Log-dose, probit and other links may represent related response shapes; model choice requires mechanistic and empirical justification.'))
s('Dose planning determines what can be estimated',kick('Avoid fitting a curve to the wrong region')+steps([('Include a meaningful control','Establish baseline or background toxicity.'),('Bracket the transition','Sample both lower and higher response regions, where feasible; do not require a universal 30–70% range.'),('Replicate and account for exposure','Dose spacing, sample size, time and measurement error affect certainty.')])+claim('An apparent EC50 can be extrapolation if the measured doses never bracket half-response.'))
s('NOAEL / LOAEL versus modeled BMD',kick('One comes from dose groups; one from a curve')+fig('toxicology_bmd','Illustrative observed dose groups and fitted adverse-effect response with NOAEL LOAEL and benchmark dose','12em')+note('NOAEL/LOAEL are study-dependent observed dose levels. BMD is fitted at a specified benchmark response; BMDL is a lower confidence bound for that modeled dose.'))
s('Exposure duration changes the interpretation',kick('One dose, more than one answer')+cards([('Acute','Single/short exposure','Different endpoints than prolonged dosing','observed'),('Repeated-dose','Weeks/months','Accumulation and adaptation may alter response','model'),('Clinical translation','Species and protocols','Do not equate experimental safety thresholds directly with a safe patient dose','warning')])+claim('A toxicity statement is incomplete without dose, route, exposure duration, species/population and endpoint.'))

s('From individual studies to cumulative evidence',kick('Systematic review → quantitative synthesis')+steps([('Define a systematic question','Population, intervention/exposure, comparator, outcome and study design.'),('Search and appraise','Include eligible studies transparently; assess bias and publication/selective reporting.'),('Synthesize','Combine comparable estimates and examine between-study differences.')])+claim('A meta-analysis is a calculation <em>inside</em> a systematic review, not a substitute for one.'))
s('How to read a forest plot',kick('Each line = one study, diamond = pooled estimate')+fig('forest_anatomy','Synthetic common-effect forest plot showing individual risk ratios and confidence intervals and green pooled diamond','13.3em')+'<div class="w10-small-note">Squares represent study estimates; square area reflects precision weight. Horizontal lines are 95% CIs. The dashed line at RR=1 is the no-effect reference.</div>')
s('Why more precise studies get more weight',kick('Common-effect model, under its assumptions')+'<div class="w10-bigmath">$w_i=1/SE_i^2,\\qquad \\hat\\theta_{pool}=\\dfrac{\\sum_i w_i\\hat\\theta_i}{\\sum_i w_i}$</div>'+cards([('High precision','Small SE','Larger inverse-variance weight','estimate'),('Low precision','Large SE','Smaller weight','uncertainty')])+note('For ratio measures, average <strong>log risk ratios / log odds ratios</strong>, then exponentiate. Pool only effects on a comparable estimand and scale.'))
s('What if studies truly differ?',kick('Between-study heterogeneity')+compare([('Common-effect','One underlying effect in the included studies','Variation attributed to sampling uncertainty'),('Random-effects','A distribution of underlying study effects','Accounts for between-study heterogeneity; requires more assumptions'),('Subgroups / sensitivity','Explore prespecified differences','Avoid assuming any pooled mean applies to all patients')],['Approach','Concept','Caution'])+claim('A narrower pooled CI is not evidence that all populations benefit equally.'))
s('Funnel plots: a clue, not a verdict',kick('Small studies, precision and selective publication')+fig('funnel_anatomy','Side by side approximately symmetric and asymmetric funnel plots with effect size and standard error axes','12.3em')+note('Asymmetry may result from publication bias, heterogeneity, methodological differences or chance; assess alongside study design and reporting.'))
s('Evidence synthesis inherits upstream weaknesses',kick('Why systematic review matters')+cards([('Garbage in','Risk of bias','Many biased studies can yield a precise biased pooled estimate','warning'),('Apples and oranges','Heterogeneity','Clinical, methodological and statistical differences must be examined','uncertainty'),('Missing evidence','Publication bias','Unpublished or selectively reported results can shift the apparent evidence','observed')])+claim('Meta-analysis increases information only insofar as the included evidence is interpretable.'))

# recap quiz slides: buttons functional via JS
quizzes=[
('Which denominator?','A negative diagnostic test is obtained. What is the probability the person is actually healthy?',[('A','Sensitivity'),('B','Specificity'),('C','Negative predictive value')],'C','NPV = TN / (TN + FN); condition on the negative test result.'),
('Best threshold?','A threshold is moved along a fixed biomarker ROC curve. What necessarily changes?',[('A','AUC'),('B','Sensitivity and specificity'),('C','Disease prevalence')],'B','Threshold selection changes the operating point, not the AUC of the fixed marker scores.'),
('Randomization?','Which statement about randomized allocation is correct?',[('A','Eliminates sampling variation'),('B','Guarantees equal covariates'),('C','Reduces systematic baseline confounding on average')],'C','Random assignment helps balance baseline causes on average, but chance imbalance remains.'),
('Meta-analysis?','Several precise studies estimate different population effects. What is most important to inspect?',[('A','Heterogeneity and applicability'),('B','Only the pooled p-value'),('C','Whether all effect estimates are identical')],'A','Underlying study effects can vary; pooled estimates need clinical context and heterogeneity assessment.')]
for j,(title,question,opts,correct,why) in enumerate(quizzes,1):
  html='<div class="w10-quiz" data-quiz="'+str(j)+'"><div class="w10-quiz-question">'+question+'</div><div class="w10-quiz-options">'+''.join(f'<button type="button" class="w10-choice" data-choice="{letter}">{letter} · {answer}</button>' for letter,answer in opts)+'</div><div class="w10-quiz-feedback" aria-live="polite"></div></div>'
  s('Check your intuition · '+title,kick('Interpret, do not memorize')+html,'exercise-slide')

s('One map: where statistics enters evidence',kick('From research question to decision')+'<div class="w10-summary-flow"><div><strong>Who?</strong><span>Population, prevalence, selection</span></div><div><strong>What?</strong><span>Diagnosis and misclassification</span></div><div><strong>Why?</strong><span>Trial causal effect and benefit–harm</span></div><div><strong>How much?</strong><span>Dose–response and uncertainty</span></div><div><strong>How sure?</strong><span>Systematic review and meta-analysis</span></div></div>'+claim('A sound interpretation requires <strong>design + estimand + measurement + uncertainty + applicability</strong>.'))
s('Next: the data do not always come one patient at a time',kick('Week 11 · time, signals, survival and prediction')+'<div class="w10-hero">Outcomes may arrive as <strong>trajectories</strong>, <strong>repeated measurements</strong> and <strong>time until an event</strong>.</div>'+cards([('Time series','Signal trajectories','Serial dependence matters','observed'),('Survival','Time-to-event','Follow-up and censoring matter','uncertainty'),('Prediction','Generalization','Validation matters','estimate')]),'section-slide')

# Consolidate two reinforcing sections to keep the lecture close to 55 slides.
slides[:] = [slide for slide in slides if not (slide.startswith('## What observations cannot guarantee ') or slide.startswith('## Evidence synthesis inherits upstream weaknesses '))]

